pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 depositAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(depositAmount > 0);

        // Use a helper to accumulate total tracked balance
        // deposit to actor
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // deposit to a different user to have some base balance
        vm.deal(address(0x1234), 100 ether);
        vm.prank(address(0x1234));
        c.deposit{value: 100 ether}();

        // Now compute total tracked balance by summing balances of both users
        uint256 totalTracked = c.balances(actor) + c.balances(address(0x1234));

        // The total deposited Ether is depositAmount + 100 ether.
        // The contract's actual balance must be at least this sum (could be more if initially funded).
        // In the correct version, totalTracked == address(c).balance exactly.
        // In the buggy version, actor's balance decreased by depositAmount, so totalTracked would be less.

        // General rule: The sum of all balances stored in the contract must equal the contract's actual Ether balance.
        // Because the contract has no other functions that can change balance without updating balances (besides creator-only migrateTo),
        // and we are not calling migrateTo, this invariant holds for the reference.
        // The buggy deposit subtracts the deposited amount from the user's balance, breaking the equality.
        assertEq(totalTracked, address(c).balance);
    }
}

