pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        // Record balance before deposit
        uint256 prevBal = address(c).balance;
        // Fund actor and deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        // After deposit, contract balance should be prevBal + amount.
        // This holds in P. In M, an overflow in balances can occur but the Ether is still received,
        // so the contract balance still increases by amount, but the sum of balances might not.
        // The invariant: the contract's Ether balance equals the sum of all user balances (here just the actor's).
        // We read the actor's balance via a public getter? There is no public getter for `balances`.
        // However, we can use the `deposit` and `withdraw` functions to indirectly test the invariant.
        // If balances[actor] overflowed, the actor cannot withdraw amount, but the contract has the Ether.
        // More robust: use the fact that after deposit, the actor must be able to withdraw the deposited amount.
        // In P, withdraw(amount) succeeds because balances[actor] == amount.
        // In M, if overflow happened, balances[actor] might be less than amount, causing revert.
        vm.prank(actor);
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

