pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, address other) public {
        vm.assume(amount > 0);
        vm.assume(other != address(this) && other != address(0) && other != address(c));
        vm.assume(other.code.length == 0);

        // Give some ether to the other actor and ourselves
        vm.deal(address(this), 1 ether);
        vm.deal(other, 1 ether);

        // Another user deposits a large amount to increase total balances
        vm.prank(other);
        c.deposit{value: uint256(amount)}();

        // Main actor deposits a crafted value that will cause overflow in balances[main] + deposit 
        // and then overflow the sum. The exact value is computed by the fuzzer through 'amount'.
        // We push the total balances to near the max by making other deposit first.
        // Now the main actor deposits an amount that overflows.
        vm.prank(address(this));
        c.deposit{value: uint256(amount)}();

        // Now perform a refund to force the balance to zero
        vm.prank(address(this));
        c.refund();

        // After refund, the balance of main actor must be zero in the reference (no overflow occurred,
        // deposit added to balance, refund zeroed it). In the buggy version, the overflow may have 
        // left the balance at something non-zero, or the deposit/refund pattern exposes the mismatch.
        // Rule: the balance after this sequence must be 0.
        assertTrue(c.balances(address(this)) == 0);
    }
}

